const coerce心情 = z
    .union([z.string(), z.coerce.number()])
    .transform((v) => {
    if (typeof v === 'string' && v.trim()) {
        return v.trim();
    }
    const n = typeof v === 'number' ? v : Number(v);
    if (!Number.isFinite(n)) {
        return '平静';
    }
    if (n >= 81) {
        return '高涨';
    }
    if (n >= 61) {
        return '愉快';
    }
    if (n >= 41) {
        return '平静';
    }
    if (n >= 21) {
        return '压抑';
    }
    return '低落';
});
