/** 已废弃的探索区域键（旧稿名或 AI 误写），加载时自动移除 */
export const DEPRECATED_EXPLORATION_AREA_KEYS = ['乱石滩营地', '乱石滩营地周边'] as const;

/** 乱石滩营地 → 湖畔营地 后，删除所有废弃键 */
export function migrate_exploration_areas(areas: Record<string, unknown>): boolean {
  let changed = false;

  if (areas['乱石滩营地'] && !areas['湖畔营地']) {
    areas['湖畔营地'] = areas['乱石滩营地'];
    changed = true;
  }

  for (const key of DEPRECATED_EXPLORATION_AREA_KEYS) {
    if (key in areas) {
      delete areas[key];
      changed = true;
      console.info('[探索区域] 已移除废弃区域:', key);
    }
  }

  return changed;
}
